INSERT INTO categories VALUES(1,'Men''s Polo T-Shirts','mens-polo-t-shirts','Meticulously tailored luxury polo t-shirts engineered from 100% Supima® cotton, Mulberry silk blends, and stay-flat structured collars.','https://images.unsplash.com/photo-1586363104862-3a5e2ab60d99?w=800&auto=format&fit=crop&q=80',1,1,'2026-08-17 20:46:25','2026-08-17 20:46:25');
