INSERT INTO products VALUES(1,'JACARIO Riviera Amalfi Silk Polo','jacario-riviera-amalfi-silk-polo','JAC-POLO-001',1,'Featherweight silk-cotton knit inspired by coastal yachting elegance with hand-stitched mother-of-pearl buttons.',unistr('Featherweight silk-cotton knit inspired by coastal yachting elegance with hand-stitched mother-of-pearl buttons.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),2499,1999,'70% Egyptian Mako Cotton, 30% Mulberry Silk','Slim Fit','Solid','Italian Spread Collar','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,1,1,NULL,'JACARIO Riviera Amalfi Silk Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Riviera Amalfi Silk Polo crafted from 70% Egyptian Mako Cotton, 30% Mulberry Silk. Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(2,'JACARIO Tuscan Olive Honeycomb Polo','jacario-tuscan-olive-honeycomb-polo','JAC-POLO-002',1,'Structured honeycomb weave with internal micro-interlining that guarantees zero collar curling through 50+ washes.',unistr('Structured honeycomb weave with internal micro-interlining that guarantees zero collar curling through 50+ washes.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),1899,1499,'100% Organic Piqué Cotton (230 GSM)','Regular Fit','Solid','Stay-Flat Ribbed Collar','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,1,1,NULL,'JACARIO Tuscan Olive Honeycomb Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Tuscan Olive Honeycomb Polo crafted from 100% Organic Piqué Cotton (230 GSM). Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(3,'JACARIO Pure Ivory Mercerized Polo','jacario-pure-ivory-mercerized-polo','JAC-POLO-003',1,'Brilliant non-translucent ivory tone with a silken sheen, reinforced side vents, and heat-sealed seams.',unistr('Brilliant non-translucent ivory tone with a silken sheen, reinforced side vents, and heat-sealed seams.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),2199,1799,'Double-Mercerized Supima® Cotton','Slim Fit','Solid','Classic 3-Button Placket','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,1,1,NULL,'JACARIO Pure Ivory Mercerized Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Pure Ivory Mercerized Polo crafted from Double-Mercerized Supima® Cotton. Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(4,'JACARIO Forest Emerald Textured Knit Polo','jacario-forest-emerald-textured-knit-polo','JAC-POLO-004',1,'Deep emerald hue woven with flexible 4-way stretch for all-day comfort in tropical and temperate climates.',unistr('Deep emerald hue woven with flexible 4-way stretch for all-day comfort in tropical and temperate climates.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),1999,1599,'Stretch Cotton Piqué (95% Cotton, 5% Elastane)','Regular Fit','Solid','Tailored Ribbed Collar','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,0,1,NULL,'JACARIO Forest Emerald Textured Knit Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Forest Emerald Textured Knit Polo crafted from Stretch Cotton Piqué (95% Cotton, 5% Elastane). Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(5,'JACARIO Royal Sapphire Johnny Collar Polo','jacario-royal-sapphire-johnny-collar-polo','JAC-POLO-005',1,'A relaxed open-collar silhouette paying homage to mid-century resort wear with a contemporary tapered hem.',unistr('A relaxed open-collar silhouette paying homage to mid-century resort wear with a contemporary tapered hem.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),2399,1899,'100% Extra-Long Staple Supima® Cotton','Relaxed Fit','Solid','Buttonless Johnny Collar','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,1,1,NULL,'JACARIO Royal Sapphire Johnny Collar Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Royal Sapphire Johnny Collar Polo crafted from 100% Extra-Long Staple Supima® Cotton. Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(6,'JACARIO Sand Dune Waffle Knit Polo','jacario-sand-dune-waffle-knit-polo','JAC-POLO-006',1,'Warm earth tone with a tactile waffle texture, engineered to stay cool and wrinkle-free all day long.',unistr('Warm earth tone with a tactile waffle texture, engineered to stay cool and wrinkle-free all day long.\u000a\u000aEngineered with JACARIO''s proprietary stay-flat collar technology that prevents edge curl even after 50+ machine washes. Features authentic cross-stitched mother-of-pearl buttons and pre-shrunk cotton yarn for a definitive silhouette that stands the test of time.'),1799,1399,'Cotton Blend (80% Cotton, 20% Microfiber)','Regular Fit','Solid','Ribbed Knit Collar','Short Sleeve with Knitted Arm Ribbing','Machine wash cold with like colors, dry flat in shade, do not tumble dry','India',0,1,0,1,NULL,'JACARIO Sand Dune Waffle Knit Polo | JACARIO Luxury Polo T-Shirts','Shop JACARIO Sand Dune Waffle Knit Polo crafted from Cotton Blend (80% Cotton, 20% Microfiber). Premium Indian pricing, express shipping, and 15-day doorstep exchanges at JACARIO.',NULL,'2026-08-17 20:46:25','2026-08-19 16:38:52');
INSERT INTO products VALUES(7,'JACARIO Essential Pitch Black Round Neck Tee','jacario-essential-pitch-black-round-neck-tee','JAC-RND-001',2,'The ultimate heavyweight black crew neck t-shirt. Clean, sculpted, and unyielding in collar shape.','Crafted from 100% organic long-staple combed cotton (220 GSM). Engineered with a high-density 1x1 rib neckline that maintains its crisp circle wash after wash without sagging.',1499,1199,'100% Organic Combed Cotton (220 GSM)','Tailored Sculpted Fit','Solid','Reinforced Seamless Crew Neck','Short Sleeve','Machine wash cold inside out','India',1,0,1,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
INSERT INTO products VALUES(8,'JACARIO Heavyweight Minimalist White Round Neck Tee','jacario-heavyweight-minimalist-white-round-neck-tee','JAC-RND-002',2,'Premium non-see-through heavyweight white crew neck tee with silky mercerized finish.','Designed for everyday luxury. Completely opaque and breathable with double-needle hems and blind-stitched sleeves for a pristine minimalist aesthetic.',1499,1199,'100% Mercerized Cotton (220 GSM)','Sculpted Regular Fit','Solid','Stay-Round Elastic Rib Collar','Short Sleeve','Machine wash cold with whites','India',1,0,1,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
INSERT INTO products VALUES(9,'JACARIO Nautical Deep Navy Round Neck Tee','jacario-nautical-deep-navy-round-neck-tee','JAC-RND-003',2,'Deep maritime navy crew neck with luminous cotton luster and ultra-soft handle.','Pre-shrunk, bio-washed cotton engineered to drape naturally over the shoulders without excess bulk around the midriff.',1499,1199,'100% Supima® Cotton','Tailored Fit','Solid','Reinforced Crew Neck','Short Sleeve','Machine wash cold','India',0,1,0,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
INSERT INTO products VALUES(10,'JACARIO Heather Grey Melange Round Neck Tee','jacario-heather-grey-melange-round-neck-tee','JAC-RND-004',2,'Classic tri-blend textured grey crew neck with athletic stretch and featherweight breathability.','Woven with multi-tonal grey fibers that offer subtle heathering and exceptional tactile comfort. Perfect under unbuttoned overshirts or jackets.',1499,1199,'95% Combed Cotton, 5% Elastane','Athletic Regular Fit','Solid','Ribbed Crew Collar','Short Sleeve','Machine wash cold','India',0,0,1,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
INSERT INTO products VALUES(11,'JACARIO Royal Sapphire Silk-Knit Polo','jacario-royal-sapphire-silk-knit-polo','JAC-NEW-001',3,'New Season Drop: Vibrant royal sapphire blue polo with fine-gauge knit and open Johnny collar.','An exquisite new arrival designed with a retro open collar (no buttons) and rib-hem finish. Crafted from pure Mulberry silk-cotton blend for unparalleled summer luxury.',3199,2699,'60% Mulberry Silk, 40% Egyptian Cotton','Relaxed Sartorial Fit','Solid','Open Riviera Johnny Collar','Short Sleeve with Ribbed Cuffs','Dry clean or gentle hand wash','India',0,1,1,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
INSERT INTO products VALUES(12,'JACARIO Forest Emerald Textured Knit Tee','jacario-forest-emerald-textured-knit-tee','JAC-NEW-002',3,'New Season Drop: Micro-waffle textured forest green crew neck tee with tailored European shoulders.','Our latest seasonal introduction featuring a subtle micro-waffle honeycomb weave that adds tactile dimensionality to a classic round neck silhouette.',1799,1499,'100% Micro-Waffle Pima Cotton (230 GSM)','Tailored Slim Fit','Solid','Ribbed Crew Neck','Short Sleeve','Machine wash cold','India',0,1,1,1,NULL,NULL,NULL,'2026-08-19 16:39:22','2026-08-17 20:46:25','2026-08-19 16:39:22');
