INSERT INTO reviews VALUES(1,1,3,NULL,5,'Incredible handfeel and fit','The fit through the shoulders and arms is tailored without being restrictive. Breathable even in humid weather. Ordered 3 more colors.',1,1,1,'2026-08-19 16:41:12','2026-08-28 18:59:02');
INSERT INTO reviews VALUES(2,2,3,NULL,4,'Exceptional craftsmanship and packaging','Arrived in a sleek embossed matte black box with tissue wrap. The fabric is heavy yet breathable. Only giving 4 stars because my preferred size XXL was low on stock!',1,1,0,'2026-08-19 16:41:12','2026-08-28 18:59:02');
INSERT INTO reviews VALUES(3,3,3,NULL,5,'Pure luxury silk-cotton blend','The Riviera Johnny collar polo is a work of art. The subtle sheen and buttery softness turn heads wherever I go. Essential summer knitwear.',1,1,1,'2026-08-19 16:41:12','2026-08-28 18:59:02');
INSERT INTO reviews VALUES(4,4,3,NULL,5,'Golf performance is top tier','Full range of motion during tee-off and keeps you bone dry throughout 18 holes. The collar remains crisp and does not curl under sweaters.',1,1,0,'2026-08-19 16:41:12','2026-08-28 18:59:02');
INSERT INTO reviews VALUES(5,5,3,NULL,5,'Unbeatable fabric and collar structure','I have bought polo shirts from Ralph Lauren, Sunspel, and Loro Piana over the years. The JACARIO Supima Polo genuinely stands toe-to-toe with luxury European houses. The collar does not roll or fray after multiple washes, and the drape is flawless.',1,1,1,'2026-08-19 16:41:12','2026-08-28 18:59:02');
