INSERT INTO settings VALUES(16,'brand_story_excerpt','At JACARIO, we do only one thing — and we do it to perfection. We obsess over the micro-details of the Polo T-Shirt: double-twisted long-staple yarns, mother-of-pearl hardware, and hand-finished collars that never curl.','2026-08-17 20:46:26','2026-08-17 20:46:26');
INSERT INTO settings VALUES(17,'shipping_policy',unistr('### Shipping & Delivery\u000aAll JACARIO orders are packaged in our signature luxury presentation box and shipped via express courier.\u000a\u000a- **Complimentary Express Shipping**: On all orders above ₹1,999.\u000a- **Standard Express Delivery (₹150)**: Delivered within 2–4 business days across major metro cities, and 3–5 business days nationwide.\u000a- **Order Tracking**: Real-time SMS and email notifications with live GPS tracking links as soon as your parcel departs our fulfillment atelier.'),'2026-08-17 20:46:26','2026-08-17 20:46:26');
INSERT INTO settings VALUES(18,'return_policy',unistr('### Returns & Exchanges\u000aWe offer a 15-day complimentary exchange and return window on all unwashed, unworn Polo T-Shirts with original tags intact.\u000a\u000a- **Hassle-free Doorstep Pickup**: Our courier partner will collect the parcel from your doorstep at no additional charge.\u000a- **Instant Store Credit or Refund**: Refunds are processed back to the original payment method within 48 hours of quality inspection at our atelier.'),'2026-08-17 20:46:26','2026-08-17 20:46:26');
INSERT INTO settings VALUES(19,'privacy_policy',unistr('### Privacy Policy\u000aYour privacy is sacred at JACARIO. We protect your personal data using industry-standard 256-bit SSL encryption. We never sell, trade, or share your contact or transaction details with unauthorized third parties.'),'2026-08-17 20:46:26','2026-08-17 20:46:26');
INSERT INTO settings VALUES(20,'terms_conditions',unistr('### Terms & Conditions\u000aWelcome to JACARIO. By accessing our platform, you agree to our standard terms of purchase, authenticity guarantees, and fair usage guidelines.'),'2026-08-17 20:46:26','2026-08-17 20:46:26');
INSERT INTO banners VALUES(1,'The Polo Collection','Meticulously tailored from 100% American Supima® cotton, Mulberry silk blends, and stay-flat collar technology.','✦ 50 Bespoke Silhouettes','Shop Supima® Series','/shop?fabric=Supima','/images/banners/banner-studio-haute.jpg',NULL,1,1,'left','2026-08-19 16:38:52','2026-08-21 16:05:10','shop');
INSERT INTO banners VALUES(2,'Mulberry Silk & 24-Gauge Knits','Ultra-fine natural luster meets athletic breathability for effortless evening elegance.','★ Rare Silk Collection','Explore Silk Knits','/shop?fabric=Silk','/images/banners/banner-silk-atelier.jpg',NULL,2,1,'left','2026-08-19 16:38:52','2026-08-21 16:05:10','shop');
INSERT INTO banners VALUES(3,'Riviera Earth & Espresso Drop','14 new season colorways inspired by Portofino coastlines and dyed with eco-friendly reactive pigments.','◆ New Season Arrivals','Shop New Arrivals','/shop?collection=new-arrivals','/images/banners/banner-riviera-earth.jpg',NULL,3,1,'left','2026-08-19 16:38:52','2026-08-21 16:05:10','shop');
INSERT INTO banners VALUES(4,'Loved. Worn. Repeated.','Our highest-rated customer icons, engineered with genuine Australian mother-of-pearl hardware.','● 4.9/5 Star Customer Icons','Shop Best Sellers','/shop?collection=bestsellers','/images/banners/banner-classic-bestseller.jpg',NULL,4,1,'right','2026-08-19 16:38:52','2026-08-21 15:57:36','hero');
INSERT INTO banners VALUES(5,'Collar Engineering That Never Curls.','Internal micro-fused interlining and reinforced plackets engineered to stay razor-sharp through 50+ washes.','✦ Atelier Craftsmanship','Explore Stay-Flat Series','/shop?fabric=Supima','/images/banners/banner-studio-haute.jpg',NULL,5,1,'right','2026-08-19 16:38:52','2026-08-21 15:57:36','hero');
INSERT INTO banners VALUES(6,'The Polo, Perfected.','Meticulously tailored from 100% long-staple American Supima® cotton with our stay-flat collar guarantee.','✦ The Haute Collection','Shop Now','/shop?fabric=Supima','/images/banners/banner-studio-haute.jpg',NULL,1,1,'right','2026-08-21 16:06:39','2026-08-21 16:06:39','hero');
INSERT INTO banners VALUES(7,'Mulberry Silk & Supima®','Silken drape meets athletic breathability. An ultra-fine 24-gauge knit engineered for effortless evening elegance.','★ Rare 24-Gauge Silk Knit','Explore Haute Knits','/shop?fabric=Silk','/images/banners/banner-silk-atelier.jpg',NULL,2,1,'right','2026-08-21 16:06:39','2026-08-21 16:06:39','hero');
INSERT INTO banners VALUES(8,'Riviera Earth & Espresso','14 new season colorways inspired by Portofino coastlines and dyed with eco-friendly reactive pigments.','◆ New Season Drop','Shop New Arrivals','/shop?collection=new-arrivals','/images/banners/banner-riviera-earth.jpg',NULL,3,1,'right','2026-08-21 16:06:39','2026-08-21 16:06:39','hero');
INSERT INTO customizable_products VALUES(1,'Customize Polo T-Shirt','polo-t-shirt','polo_tshirt','Engineered from signature 240 GSM double-pique cotton with reinforced knit collar and mother-of-pearl buttons. Bespoke embroidery & HD printing ready.','Craft your bespoke JACARIO Polo T-Shirt. Crafted from 100% long-staple Supima® double-pique cotton, featuring our structured anti-curl collar, tailored sleeves, and refined split-hem. Personalize with your custom logo artwork, brand initials, or typography with state-of-the-art print precision.',1499,1299,'JAC-CUST-POLO','images/customizer/polo/black.jpg','{"front":"images\/customizer\/polo\/{color}.jpg"}',1,1,'2026-08-28 18:49:57','2026-08-29 09:40:33');
INSERT INTO customizable_products VALUES(2,'Customize T-Shirt','t-shirt','tshirt','Ultra-luxurious 220 GSM combed Supima® crewneck jersey. Ultra-soft touch, tailored modern fit, zero shrinkage.','Create your signature luxury Crewneck T-Shirt. Made with premium combed compact organic cotton, designed for seamless drape, incredible breathability, and long-lasting durability. Upload your graphics or craft custom typography with precision placement.',999,849,'JAC-CUST-TSHIRT','images/customizer/tshirt/black.jpg','{"front":"images\/customizer\/tshirt\/{color}.jpg"}',1,2,'2026-08-28 18:49:57','2026-08-29 09:40:33');
