PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "role" varchar not null default 'customer', "avatar" varchar, "is_active" tinyint(1) not null default '1', "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "image" varchar, "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sizes" ("id" integer primary key autoincrement not null, "name" varchar not null, "code" varchar not null, "chest" varchar, "length" varchar, "shoulder" varchar, "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "colors" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "hex_code" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "sku" varchar not null, "category_id" integer not null, "short_description" text, "description" text, "base_price" numeric not null, "sale_price" numeric, "fabric" varchar not null default '100% Supima Cotton', "fit" varchar not null default 'Classic Fit', "pattern" varchar not null default 'Solid', "collar_type" varchar not null default 'Ribbed Polo Collar', "sleeve_type" varchar not null default 'Short Sleeve', "wash_care" varchar not null default 'Machine wash cold, tumble dry low', "country_of_origin" varchar not null default 'India', "is_bestseller" tinyint(1) not null default '0', "is_new_arrival" tinyint(1) not null default '0', "is_featured" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "size_chart" text, "seo_title" varchar, "seo_description" text, "deleted_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("category_id") references "categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "product_variants" ("id" integer primary key autoincrement not null, "product_id" integer not null, "size_id" integer not null, "color_id" integer not null, "sku" varchar not null, "price" numeric, "sale_price" numeric, "stock_quantity" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("size_id") references "sizes"("id") on delete cascade, foreign key("color_id") references "colors"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "product_images" ("id" integer primary key autoincrement not null, "product_id" integer not null, "color_id" integer, "image_path" varchar not null, "alt_text" varchar, "is_primary" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("color_id") references "colors"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "carts" ("id" integer primary key autoincrement not null, "user_id" integer, "session_id" varchar, "coupon_code" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "wishlists" ("id" integer primary key autoincrement not null, "user_id" integer not null, "product_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "addresses" ("id" integer primary key autoincrement not null, "user_id" integer not null, "full_name" varchar not null, "phone" varchar not null, "address_line_1" varchar not null, "address_line_2" varchar, "landmark" varchar, "city" varchar not null, "state" varchar not null, "postal_code" varchar not null, "country" varchar not null default 'India', "address_type" varchar not null default 'home', "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "coupons" ("id" integer primary key autoincrement not null, "code" varchar not null, "description" text, "discount_type" varchar not null default 'percentage', "value" numeric not null, "min_order_value" numeric not null default '0', "max_discount" numeric, "usage_limit" integer, "usage_limit_per_user" integer not null default '1', "used_count" integer not null default '0', "starts_at" datetime, "expires_at" datetime, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "coupon_usages" ("id" integer primary key autoincrement not null, "coupon_id" integer not null, "user_id" integer, "order_id" integer, "discount_amount" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("coupon_id") references "coupons"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "order_number" varchar not null, "user_id" integer, "subtotal" numeric not null, "discount_amount" numeric not null default '0', "shipping_amount" numeric not null default '0', "tax_amount" numeric not null default '0', "total_amount" numeric not null, "coupon_code" varchar, "status" varchar not null default 'pending', "payment_method" varchar not null default 'razorpay', "payment_status" varchar not null default 'pending', "customer_name" varchar not null, "customer_email" varchar not null, "customer_phone" varchar not null, "shipping_address" text not null, "billing_address" text, "tracking_number" varchar, "courier_name" varchar, "notes" text, "cancelled_reason" text, "shipped_at" datetime, "delivered_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "order_id" integer not null, "payment_id" varchar, "razorpay_order_id" varchar, "razorpay_signature" varchar, "payment_method" varchar not null default 'razorpay', "currency" varchar not null default 'INR', "amount" numeric not null, "status" varchar not null default 'pending', "payload" text, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "reviews" ("id" integer primary key autoincrement not null, "product_id" integer not null, "user_id" integer not null, "order_id" integer, "rating" integer not null default '5', "title" varchar, "comment" text not null, "is_verified_purchase" tinyint(1) not null default '0', "is_approved" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "newsletter_subscribers" ("id" integer primary key autoincrement not null, "email" varchar not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "banners" ("id" integer primary key autoincrement not null, "title" varchar not null, "subtitle" varchar, "badge_text" varchar, "cta_text" varchar not null default 'Shop Now', "cta_url" varchar not null default '/shop', "image_path" varchar not null, "mobile_image_path" varchar, "sort_order" integer not null default '1', "is_active" tinyint(1) not null default '1', "text_alignment" varchar not null default 'left', "created_at" datetime, "updated_at" datetime, "position" varchar not null default 'hero');
CREATE TABLE IF NOT EXISTS "customizable_products" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "type" varchar check ("type" in ('polo_tshirt', 'tshirt')) not null default 'polo_tshirt', "short_description" text, "description" text, "base_price" numeric not null default '1499', "discount_price" numeric, "sku" varchar not null, "featured_image" varchar, "mockup_views" text, "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customizable_product_variants" ("id" integer primary key autoincrement not null, "customizable_product_id" integer not null, "size_id" integer not null, "color_id" integer not null, "stock_quantity" integer not null default '100', "price_override" numeric, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("customizable_product_id") references "customizable_products"("id") on delete cascade, foreign key("size_id") references "sizes"("id") on delete cascade, foreign key("color_id") references "colors"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customization_settings" ("id" integer primary key autoincrement not null, "customizable_product_id" integer not null, "allow_front" tinyint(1) not null default '1', "allow_back" tinyint(1) not null default '0', "allowed_file_types" text, "max_file_size_mb" integer not null default '15', "allowed_fonts" text, "min_text_len" integer not null default '1', "max_text_len" integer not null default '40', "max_images" integer not null default '4', "print_area" text, "base_customization_fee" numeric not null default '0', "extra_image_fee" numeric not null default '100', "extra_text_fee" numeric not null default '50', "bulk_pricing" text, "created_at" datetime, "updated_at" datetime, foreign key("customizable_product_id") references "customizable_products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "saved_custom_designs" ("id" integer primary key autoincrement not null, "user_id" integer not null, "customizable_product_id" integer not null, "color_id" integer, "size_id" integer, "title" varchar not null default 'My Custom Design', "design_data" text not null, "preview_path" varchar, "artwork_paths" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("customizable_product_id") references "customizable_products"("id") on delete cascade, foreign key("color_id") references "colors"("id") on delete set null, foreign key("size_id") references "sizes"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "cart_items" ("id" integer primary key autoincrement not null, "cart_id" integer not null, "product_variant_id" integer, "quantity" integer not null default ('1'), "unit_price" numeric not null, "created_at" datetime, "updated_at" datetime, "is_customized" tinyint(1) not null default '0', "customizable_product_id" integer, "custom_color_id" integer, "custom_size_id" integer, "customization_data" text, "customization_preview_path" varchar, "artwork_file_path" varchar, "artwork_files" text, "customization_fee" numeric not null default '0', foreign key("product_variant_id") references product_variants("id") on delete cascade on update no action, foreign key("cart_id") references carts("id") on delete cascade on update no action, foreign key("customizable_product_id") references "customizable_products"("id") on delete set null, foreign key("custom_color_id") references "colors"("id") on delete set null, foreign key("custom_size_id") references "sizes"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer, "product_variant_id" integer, "product_name" varchar not null, "size_name" varchar not null, "color_name" varchar not null, "color_hex" varchar, "sku" varchar not null, "image_path" varchar, "unit_price" numeric not null, "quantity" integer not null, "subtotal" numeric not null, "created_at" datetime, "updated_at" datetime, "is_customized" tinyint(1) not null default '0', "customizable_product_id" integer, "customization_data" text, "customization_preview_path" varchar, "artwork_file_path" varchar, "artwork_files" text, "customization_fee" numeric not null default '0', "custom_production_status" varchar not null default 'pending', foreign key("product_variant_id") references product_variants("id") on delete set null on update no action, foreign key("product_id") references products("id") on delete set null on update no action, foreign key("order_id") references orders("id") on delete cascade on update no action, foreign key("customizable_product_id") references "customizable_products"("id") on delete set null);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "categories_slug_unique" on "categories" ("slug");
CREATE UNIQUE INDEX "sizes_code_unique" on "sizes" ("code");
CREATE UNIQUE INDEX "colors_slug_unique" on "colors" ("slug");
CREATE UNIQUE INDEX "products_slug_unique" on "products" ("slug");
CREATE UNIQUE INDEX "products_sku_unique" on "products" ("sku");
CREATE INDEX "products_is_bestseller_index" on "products" ("is_bestseller");
CREATE INDEX "products_is_new_arrival_index" on "products" ("is_new_arrival");
CREATE INDEX "products_is_featured_index" on "products" ("is_featured");
CREATE INDEX "products_is_active_index" on "products" ("is_active");
CREATE UNIQUE INDEX "prod_variant_unique" on "product_variants" ("product_id", "size_id", "color_id");
CREATE UNIQUE INDEX "product_variants_sku_unique" on "product_variants" ("sku");
CREATE INDEX "carts_session_id_index" on "carts" ("session_id");
CREATE UNIQUE INDEX "wishlists_user_id_product_id_unique" on "wishlists" ("user_id", "product_id");
CREATE UNIQUE INDEX "coupons_code_unique" on "coupons" ("code");
CREATE UNIQUE INDEX "orders_order_number_unique" on "orders" ("order_number");
CREATE INDEX "orders_status_index" on "orders" ("status");
CREATE INDEX "orders_payment_status_index" on "orders" ("payment_status");
CREATE INDEX "payments_payment_id_index" on "payments" ("payment_id");
CREATE INDEX "payments_razorpay_order_id_index" on "payments" ("razorpay_order_id");
CREATE UNIQUE INDEX "newsletter_subscribers_email_unique" on "newsletter_subscribers" ("email");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
CREATE INDEX "banners_sort_order_index" on "banners" ("sort_order");
CREATE INDEX "banners_is_active_index" on "banners" ("is_active");
CREATE INDEX "banners_position_index" on "banners" ("position");
CREATE UNIQUE INDEX "customizable_products_slug_unique" on "customizable_products" ("slug");
CREATE UNIQUE INDEX "customizable_products_sku_unique" on "customizable_products" ("sku");
CREATE UNIQUE INDEX "cust_prod_variant_unique" on "customizable_product_variants" ("customizable_product_id", "size_id", "color_id");
CREATE UNIQUE INDEX "customization_settings_customizable_product_id_unique" on "customization_settings" ("customizable_product_id");
CREATE UNIQUE INDEX "cart_items_cart_id_product_variant_id_unique" on "cart_items" ("cart_id", "product_variant_id");
PRAGMA writable_schema=OFF;
COMMIT;
